param([string]$InputReport='conformance/mutation-debt-latest.json',[string]$OutputReport='conformance/mutation-debt-reviewed.json')
$ErrorActionPreference='Stop'
$root=Split-Path -Parent $PSScriptRoot
if(!(Test-Path -LiteralPath $root -PathType Container)){throw 'Missing checkout'}
Push-Location -LiteralPath $root
try {
 $report=Get-Content -LiteralPath $InputReport -Raw|ConvertFrom-Json -AsHashtable
 $counts=[ordered]@{}
 foreach($file in $report.files){foreach($item in $file.outstanding){
  $s=$item.statement;$replacement=$item.replacement;$decision='OPEN_REVIEW';$reason='No approved invariant or executed witness yet.'
  if($item.status -eq 'Timeout'){$decision='INCONCLUSIVE_TIMEOUT';$reason='Mutation can make the loop nonterminating. Watchdog expiry is inconclusive and is never counted as a demonstrated assertion kill.'}
  elseif($s -like '*checked(a.Scale+b.Scale)*'){$decision='OPEN_EXTREME_CHAIN_GUARD';$reason='Public exact half/double cycles can retain a small fraction while increasing DecimalScale. Checked Int32 overflow is meaningful at extreme chain lengths; no efficient black-box witness was executed. Guard remains in production.'}
  elseif($item.mutator -eq 'String mutation' -and $s -like '*throw*'){
   if($s -like '*Incompatible dimensions*'){$decision='OPEN_ERROR_CATEGORY_WITNESS';$reason='This message drives observer categorization; it is behavioral, not merely English diagnostic text.'}
   elseif($s -like '*value.Denominator.Sign*'){$decision='UNREACHABLE_NORMALIZATION_GUARD';$reason='Private Check receives normalized Rational values. FromNumeric(default(Rational)) rejects at Ratio(0,0) before Check; no reflection/unsafe injection is claimed.'}
   elseif($s -like '*result.Count!=entries.Count*'){$decision='FIXED_CATALOG_UNREACHABLE';$reason='The exact immutable44-entry catalog constructor supplies every fixed key. This future-maintenance tripwire has no failing current public input; decision is bound to retained source hashes.'}
   else{$decision='DIAGNOSTIC_TEXT_VARIATION';$reason='Observable wording changes, not identical behavior. The declared profile checks result, failure stage, exception type/category and specifically tested public argument names; exact English wording/stack traces are outside that contract. Not a kill.'}
  }
  elseif($s -like '*value.Denominator.Sign*'){$decision='UNREACHABLE_NORMALIZATION_GUARD';$reason='All private constructor call paths first construct a normalized Rational; an invalid denominator is rejected earlier. Excludes reflection/unsafe state fabrication.'}
  elseif($s -like '*scale is < -8192 or >8192*'){$decision='REDUNDANT_PROFILE_REJECTION';$reason='FromDecimal is called by the parser (scale bounded4096) or decimal128 rounding (nonzero coefficient at most35digits; zero returns scale0). At absolute scale8192 or greater, nonzero results already violate the16384-bit numerator/denominator budget and are rejected by Check. Private parameter/message differences are not identical diagnostics.'}
  elseif($s -like '*digits.Length==0*'){$decision='DELEGATED_FORMAT_REJECTION';$reason='If no coefficient digits exist, BigInteger.Parse(empty) still throws FormatException. Valid inputs and exception category are unchanged; diagnostic wording differs.'}
  elseif($s -like '*!double.IsFinite(value)*'){$decision='DELEGATED_NONFINITE_REJECTION';$reason='JavaNumberText.Format independently rejects nonfinite values with ArgumentOutOfRangeException. Public value parameter and finite-input behavior remain the same.'}
  elseif($s -like '*value>=9223372036854775808d?long.MaxValue*'){$decision='NET10_SATURATING_CAST_EQUIVALENCE';$reason='Only the2^63 boundary changes branch; .NET9+ CoreCLR floating-to-Int64 casts saturate to long.MaxValue. Supported-runtime bound, not a claim for older/alternate runtimes or executed Ubuntu qualification. Primary reference: https://learn.microsoft.com/en-us/dotnet/core/compatibility/jit/9.0/fp-to-integer'}
  elseif($s -like '*Fraction.Numerator.IsZero||other.Fraction.Numerator.IsZero*'){$decision='NORMALIZED_ZERO_VALUE_EQUIVALENCE';$reason='The ordinary arithmetic path still narrows numeric zero to Integer0 with scale0 and identical promotion. Allocation/reference identity can change; universal zero interning is not promised (Integer(0) already allocates).'}
  elseif($replacement -eq 'exponent>0' -or $replacement -eq 'scale>0' -or $replacement -eq 'Exponent>0'){$decision='ZERO_POWER_EQUIVALENCE';$reason='Branches differ only at exponent/scale zero. Multiplication or division by10^0 is identity; Integer1 and Ratio(1,1) normalize identically. Prefix identity normalization also drops the unit factor.'}
  elseif($s -like '*exponent>=0?numerator*' -and $replacement -like '*numerator<=denominator*'){$decision='POSITIVE_DECADE_INTEGER_NORMALIZATION';$reason='Equality can change requested precision only for an exact nonnegative decade10^k. The numeric result is unchanged and narrows to Integer, discarding decimal scale. Negative fractional decades are separately challenged by the pinned scale73 witness.'}
  elseif($s -like '*ToDouble()=>Kind==JavaNumberKind.Binary64*'){$decision='ROUNDTRIP_INVARIANT_EQUIVALENCE';$reason='A Binary64 member retains its Java shortest round-trip decimal fraction. Exact rational-to-double rounding reconstructs the same finite bits. Conditional on those formatter/rounding contracts; retained differential/property campaigns are not a formal proof over all64-bit patterns.'}
  elseif($file.file -eq 'JavaNumber.cs' -and $s -like '*GetHashCode()*'){$decision='HASH_ALGORITHM_VARIATION';$reason='Exact hash values are unspecified. This alternative remains equal-object hash consistent; full-scope tests and the bounded converter hash-quality property were replayed. No universal distribution or performance equivalence claim.'}
  elseif($s -like '*degree==0*'){$decision='DELEGATED_ZERO_DENOMINATOR_REJECTION';$reason='Rational(1,0) independently throws DivideByZeroException. The guard protects a clearer message; diagnostic text/stack location is not identical.'}
  elseif($item.mutator -eq 'Remove checked expression'){
   if($s -like '*PowerStep*'){$decision='BOUNDED_EXPONENT_EQUIVALENCE';$reason='Stored Power factors have radix>=2 and a16384-bit value budget. Exponent magnitude is at most16384; negation and an intermediate sum at most32768 cannot overflow Int32. Excludes reflection/unsafe state injection.'}
   else{$decision='BIGINTEGER_CAST_EQUIVALENCE';$reason='BigInteger-to-Int32 explicit conversion itself checks range, even outside a checked expression. Product exponents are additionally bounded1024; dimension-map overflow is directly tested.'}
  }
  elseif($s -like '*ArgumentNullException.ThrowIfNull(target);if(Unit.Equals*'){$decision='DELEGATED_NULL_TARGET_REJECTION';$reason='Without the outer guard, Equals(null) is false and Unit.GetConverterTo(null) throws the same ArgumentNullException naming target.'}
  elseif($s -like '*!converter.IsAffine*'){$decision='DELEGATED_NONLINEAR_REJECTION';$reason='AffineCoefficients independently rejects nonlinear converters with NotSupportedException. Relative affine success and nonlinear rejection are both tested; message/stack differences remain observable.'}
  elseif($s -like '*else if(!Unit.Equals(target)*'){$decision='IDENTITY_BRANCH_EQUIVALENCE';$reason='If the left unit differs, the first OR term dominates unchanged. If it equals its system unit, its converter/inverse is identity, so the changed right term only applies or skips an identity conversion.'}
  elseif($s -like '*if(power.Numerator.IsZero)return*'){$decision='EMPTY_POWER_ACCUMULATION_EQUIVALENCE';$reason='Zero power is introduced by Pow(0) into a fresh result map. Recursing product factors merely removes absent zero terms; no observable product remains. Bounded work/allocation can differ.'}
  elseif($s -like '*if(power<0)*' -and $replacement -eq 'power<=0'){$decision='NONZERO_FACTOR_INVARIANT';$reason='Product normalization removes zero exponents before converter evaluation. Even an identity zero power would not execute the conversion loop.'}
  elseif($item.mutator -like '*FirstOrDefault*' -and $s -like '*result.Count==1*'){$decision='NONEMPTY_COLLECTION_EQUIVALENCE';$reason='The Count==1 guard ensures First and FirstOrDefault return the same existing pair.'}
  elseif($s -like '*entry?.Field==*'){$decision='CLOSED_CATALOG_ALIAS_EQUIVALENCE';$reason='Nonnull entries return before this branch; the ONE field comparison is dead. The lowercase one alias with an identity dimensionless definition already matches the fixed catalog. The independently tested1 alias is retained. Bound to current catalog/source hashes.'}
  elseif($s -like '*return entry is not null?coherent.Alternate*'){$decision='EARLIER_RETURN_INVARIANT';$reason='A nonnull entry already returned FromCatalog earlier. The current branch can only choose Base; changing it to false is equivalent for current public inputs.'}
  elseif($s -like '*OrderByDescending(pair=>pair.Key.Length)*' -or $s -like '*prefixExponent=prefix.Value;break*'){$decision='CLOSED_PREFIX_CATALOG_EQUIVALENCE';$reason='Only decimal d/da prefixes overlap, and the fixed coherent unit symbols have no matching a-prefixed suffix that yields a second candidate. Ordering/break cannot replace an already matched parent. Not a general extensible-catalog claim.'}
  elseif($s -like '*symbol??unit.Symbol*'){$decision='CLOSED_CATALOG_OVERRIDE_INVARIANT';$reason='Every current explicit symbol override is on a transformed unit whose intrinsic Symbol is null; all remaining calls pass no override. Swapping coalescing order cannot change these fixed catalog calls.'}
  elseif($s -like '*result.Count!=entries.Count*'){$decision='FIXED_CATALOG_UNREACHABLE';$reason='The exact immutable44-entry constructor adds every fixed catalog key. The guard is a future-maintenance tripwire, not reachable by a current public input.'}
  elseif($s -like '*ArgumentNullException.ThrowIfNull(definition);original*'){$decision='DELEGATED_NULL_DEFINITION_REJECTION';$reason='JavaUnit.FromDefinition independently throws ArgumentNullException naming definition before any native data is accessed.'}
  elseif($file.file -eq 'SiPrefixes.cs' -and $s -eq 'ArgumentNullException.ThrowIfNull(unit);'){$decision='DELEGATED_NULL_UNIT_REJECTION';$reason='The surviving outer Apply guard delegates to ApplyExact, which independently rejects null with ArgumentNullException naming unit. The direct ApplyExact path is tested.'}
  $item.reviewedDisposition=$decision;$item.rationale=$reason
  if(!$counts.Contains($decision)){$counts[$decision]=0};$counts[$decision]++
 }}
 $report.reviewedDispositionCounts=$counts
 $report.reviewPolicy='Source-inspection dispositions are conditional engineering judgments, not formal proof or raw mutation kills. Diagnostic and hash variations remain explicitly observable. Independent agent review is retained separately.'
 $report|ConvertTo-Json -Depth 16|Set-Content -LiteralPath $OutputReport
 $counts|ConvertTo-Json
} finally {Pop-Location}
